// Which tokens reach the platforms, and naming helpers shared by the formats.
import type { DtcgColor, Token } from "./tokens.ts";

export const GENERATED_HEADER =
  "Generated by @htco/design-tokens from design/tokens. Do not edit; run `pnpm tokens`.";

/**
 * Primitives exist only so semantic tokens can reference them: the palette ramps, the raw
 * brand colours and the breakpoints (which CSS custom properties cannot drive) stay unpublished.
 */
export function isPublished(token: Token): boolean {
  const [group, subgroup] = token.path;
  if (group === "palette" || group === "breakpoint") return false;
  return !(group === "color" && subgroup === "brand");
}

/**
 * Web-only effects (frosted glass, the designed ground behind it) and the Settings swatches stay
 * out of native outputs.
 */
export function isNative(token: Token): boolean {
  if (!isPublished(token)) return false;
  const [group, subgroup] = token.path;
  return (
    group !== "glass" && !(group === "color" && (subgroup === "bloom" || subgroup === "swatch"))
  );
}

/** Semantic colours and elevation change with the theme; everything else is the same in both. */
export function isThemed(token: Token): boolean {
  return token.type === "color" || token.path[0] === "elevation";
}

/** `color.bg.canvas` is published as `bg.canvas`, matching the brand book. */
export function publishedPath(token: Token): string[] {
  return token.path[0] === "color" ? token.path.slice(1) : token.path;
}

const words = (parts: string[]): string[] => parts.flatMap((part) => part.split("-"));
const capitalize = (word: string): string => word.charAt(0).toUpperCase() + word.slice(1);

export const pascal = (parts: string[]): string => words(parts).map(capitalize).join("");

export function camel(parts: string[]): string {
  const name = pascal(parts);
  return name.charAt(0).toLowerCase() + name.slice(1);
}

const channels = (color: DtcgColor): [number, number, number] => [
  parseInt(color.hex.slice(1, 3), 16),
  parseInt(color.hex.slice(3, 5), 16),
  parseInt(color.hex.slice(5, 7), 16),
];

/** `#AARRGGBB` in upper case, as XAML and Compose expect. */
export function argb(color: DtcgColor): string {
  const alpha = Math.round((color.alpha ?? 1) * 255);
  const hex = [alpha, ...channels(color)].map((n) => n.toString(16).padStart(2, "0"));
  return `#${hex.join("").toUpperCase()}`;
}

/** Opaque colours as `#rrggbb`; translucent ones as `rgba(r, g, b, alpha)`. */
export function cssColor(color: DtcgColor): string {
  const alpha = color.alpha ?? 1;
  if (alpha === 1) return color.hex.toLowerCase();
  // The legacy syntax, as Design 1C writes it: browsers keep its alpha at 8 bits, the same
  // value the design renders with.
  return `rgba(${channels(color).join(", ")}, ${String(alpha)})`;
}
